#define PERL_THROW_ERROR_LOAD_ABI_MODULE_PERL_API_VERSION_MISMATCH(ma_arg1, ma_arg2, ma_arg3) \
    STMT_START { \
        dTHX; \
        const char * const in_arg1 = (const char *)(ma_arg1); \
        const char * const in_arg2 = (const char *)(ma_arg2); \
        const char * const in_arg3 = (const char *)(ma_arg3); \
        AV * const params_av = MUTABLE_AV(sv_2mortal(MUTABLE_SV(newAV()))); \
         \
        SV * const tmpl_arg1 = Perl_diag_setup_param(aTHX_ params_av, perl_diag_error_load_abi_module_perl_api_version_mismatch_idx, 0, 0, perl_diag_selector_invalid); \
        sv_setpvf(tmpl_arg1, "%s", in_arg1); \
         \
        SV * const tmpl_arg2 = Perl_diag_setup_param(aTHX_ params_av, perl_diag_error_load_abi_module_perl_api_version_mismatch_idx, 1, 0, perl_diag_selector_invalid); \
        sv_setpvf(tmpl_arg2, "%s", in_arg2); \
         \
        SV * const tmpl_arg3 = Perl_diag_setup_param(aTHX_ params_av, perl_diag_error_load_abi_module_perl_api_version_mismatch_idx, 2, 0, perl_diag_selector_invalid); \
        sv_setpvf(tmpl_arg3, "%s", in_arg3); \
         \
        SV * const message_sv = NULL; \
        Perl_diag_croak_nocontext_sv(perl_diag_error_load_abi_module_perl_api_version_mismatch_idx, params_av, message_sv); \
    } STMT_END

